CREATE PROCEDURE [bud].[jsGetBudgetSap]  AS  BEGIN      SET NOCOUNT ON;        DECLARE @ServerName NVARCHAR(100);      DECLARE @OilDatabase NVARCHAR(100);      DECLARE @BeverageDatabase NVARCHAR(100);      DECLARE @SQL NVARCHAR(MAX);        -- Get configuration values      SELECT @ServerName = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'ServerName';      SELECT @OilDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'OilDatabase';      SELECT @BeverageDatabase = ConfigValue FROM jsConfiguration WHERE ConfigKey = 'BeverageDatabase';        BEGIN TRY          -- Temp table without flag          CREATE TABLE #TempWithoutFlag (              Branch NVARCHAR(50),              DocEntry INT,              ObjectName NVARCHAR(100),              ObjType INT,              LineNum INT,              VisOrder INT,              AcctCode NVARCHAR(50),              AcctName NVARCHAR(100),              CardCode NVARCHAR(50),              CardName NVARCHAR(200),              EFFECTMONTH NVARCHAR(50),              BUDGET NVARCHAR(50),              SUB_BUDGET NVARCHAR(50),              STATE NVARCHAR(50),              DocDate DATETIME,              CreateDate DATETIME,              AMOUNT DECIMAL(18, 2),              CURRENTMONTH NVARCHAR(50),              Current_month_Posted_Amount DECIMAL(18, 2),              Budget_Owner NVARCHAR(100),              OwnerCode NVARCHAR(50),              ApproverName NVARCHAR(100),              ApprovalCode NVARCHAR(50),              Current_month_Budget DECIMAL(18, 2),              Status NVARCHAR(10),              U_NAME NVARCHAR(100),              CreatedDate DATETIME,              CreateTime NVARCHAR(50),              LineRemarks NVARCHAR(500),              Comments NVARCHAR(MAX),              ProcesStat NVARCHAR(10),              UpdateDate DATETIME,              OcrCode NVARCHAR(500),              ACOMMENT NVARCHAR(MAX),              VCOMMENT NVARCHAR(MAX),              VerifiedStatus NVARCHAR(10),              ApprovedStatus NVARCHAR(10)          );            -- Pull data from HANA          SET @SQL = N'INSERT INTO #TempWithoutFlag EXEC(''CALL "' + @OilDatabase + '"."DRAFT_APPROVAL"'') AT ' + @ServerName;          EXEC sp_executesql @SQL;            -- Temp table with flag          CREATE TABLE #TempTable (              Branch NVARCHAR(50),              DocEntry INT,              ObjectName NVARCHAR(100),              ObjType INT,              LineNum INT,              VisOrder INT,              AcctCode NVARCHAR(50),              AcctName NVARCHAR(100),              CardCode NVARCHAR(50),              CardName NVARCHAR(200),              EFFECTMONTH NVARCHAR(50),              BUDGET NVARCHAR(50),              SUB_BUDGET NVARCHAR(50),              STATE NVARCHAR(50),              DocDate DATETIME,              CreateDate DATETIME,              AMOUNT DECIMAL(18, 2),              CURRENTMONTH NVARCHAR(50),              Current_month_Posted_Amount DECIMAL(18, 2),              Budget_Owner NVARCHAR(100),              OwnerCode NVARCHAR(50),              ApproverName NVARCHAR(100),              ApprovalCode NVARCHAR(50),              Current_month_Budget DECIMAL(18, 2),              Status NVARCHAR(10),              U_NAME NVARCHAR(100),              CreatedDate DATETIME,              CreateTime NVARCHAR(50),              LineRemarks NVARCHAR(500),              Comments NVARCHAR(MAX),              ProcesStat NVARCHAR(10),              UpdateDate DATETIME,              OcrCode NVARCHAR(500),              ACOMMENT NVARCHAR(MAX),              VCOMMENT NVARCHAR(MAX),              VerifiedStatus NVARCHAR(10),              ApprovedStatus NVARCHAR(10),              Flag VARCHAR(1)          );            INSERT INTO #TempTable          SELECT *, 'A' AS Flag FROM #TempWithoutFlag;            -- First, handle updates when UpdateDate has changed          -- For existing records with different UpdateDate, update the Flag to 'I'          UPDATE J          SET J.Flag = 'I',              J.Branch = T.Branch,              J.ObjectName = T.ObjectName,              J.AcctCode = T.AcctCode,              J.AcctName = T.AcctName,              J.CardCode = T.CardCode,              J.CardName = T.CardName,              J.EFFECTMONTH = T.EFFECTMONTH,              J.BUDGET = T.BUDGET,              J.SUB_BUDGET = T.SUB_BUDGET,              J.STATE = T.STATE,              J.DocDate = T.DocDate,              J.CreateDate = T.CreateDate,              J.AMOUNT = T.AMOUNT,              J.CURRENTMONTH = T.CURRENTMONTH,              J.Current_month_Posted_Amount = T.Current_month_Posted_Amount,              J.Budget_Owner = T.Budget_Owner,              J.OwnerCode = T.OwnerCode,              J.[Approver Name] = T.ApproverName,              J.ApprovalCode = T.ApprovalCode,              J.Current_month_Budget = T.Current_month_Budget,              J.Status = T.Status,              J.U_NAME = T.U_NAME,              J.CreatedDate = T.CreatedDate,              J.CreateTime = T.CreateTime,              J.LineRemarks = T.LineRemarks,              J.Comments = T.Comments,              J.ProcesStat = T.ProcesStat,              J.UpdateDate = T.UpdateDate,              J.OcrCode = T.OcrCode,              J.ACOMMENT = T.ACOMMENT,              J.VCOMMENT = T.VCOMMENT,              J.VerifiedStatus = T.VerifiedStatus,              J.ApprovedStatus = T.ApprovedStatus          FROM bud.jsBudgetTable J          INNER JOIN #TempTable T ON               J.DocEntry = T.DocEntry               AND J.LineNum = T.LineNum               AND J.VisOrder = T.VisOrder              AND J.ObjType = T.ObjType          WHERE (J.UpdateDate IS NULL AND T.UpdateDate IS NOT NULL)             OR (J.UpdateDate IS NOT NULL AND T.UpdateDate IS NULL)             OR (J.UpdateDate <> T.UpdateDate);            -- Insert new records (that don't exist yet)          INSERT INTO bud.jsBudgetTable          SELECT * FROM #TempTable T          WHERE NOT EXISTS (              SELECT 1 FROM bud.jsBudgetTable J              WHERE J.DocEntry = T.DocEntry                 AND J.LineNum = T.LineNum                 AND J.VisOrder = T.VisOrder                AND J.ObjType = T.ObjType          );            -- Declare variables for cursor          DECLARE               @Branch NVARCHAR(50), @DocEntry INT, @ObjectName NVARCHAR(100), @ObjType INT,              @LineNum INT, @VisOrder INT, @AcctCode NVARCHAR(50), @AcctName NVARCHAR(100),              @CardCode NVARCHAR(50), @CardName NVARCHAR(200), @EFFECTMONTH NVARCHAR(50),              @BUDGET NVARCHAR(50), @SUB_BUDGET NVARCHAR(50), @STATE NVARCHAR(50),              @DocDate DATETIME, @CreateDate DATETIME, @AMOUNT DECIMAL(18,2),              @CURRENTMONTH NVARCHAR(50), @Current_month_Posted_Amount DECIMAL(18,2),              @Budget_Owner NVARCHAR(100), @OwnerCode NVARCHAR(50),              @ApproverName NVARCHAR(100), @ApprovalCode NVARCHAR(50),              @Current_month_Budget DECIMAL(18,2), @Status NVARCHAR(10), @U_NAME NVARCHAR(100),              @CreatedDate DATETIME, @CreateTime NVARCHAR(50), @LineRemarks NVARCHAR(500),              @Comments NVARCHAR(MAX), @ProcesStat NVARCHAR(10), @UpdateDate DATETIME,              @OcrCode NVARCHAR(500), @ACOMMENT NVARCHAR(MAX), @VCOMMENT NVARCHAR(MAX),              @VerifiedStatus NVARCHAR(10), @ApprovedStatus NVARCHAR(10),@Flag NVARCHAR(10);            DECLARE @DatabaseName NVARCHAR(100), @SQLQuery NVARCHAR(MAX), @CheckQuery NVARCHAR(MAX), @RecordExists INT;            DECLARE record_cursor CURSOR FOR          SELECT * FROM #TempTable;            OPEN record_cursor;          FETCH NEXT FROM record_cursor INTO               @Branch, @DocEntry, @ObjectName, @ObjType, @LineNum, @VisOrder,              @AcctCode, @AcctName, @CardCode, @CardName, @EFFECTMONTH, @BUDGET,              @SUB_BUDGET, @STATE, @DocDate, @CreateDate, @AMOUNT, @CURRENTMONTH,              @Current_month_Posted_Amount, @Budget_Owner, @OwnerCode, @ApproverName,              @ApprovalCode, @Current_month_Budget, @Status, @U_NAME, @CreatedDate,              @CreateTime, @LineRemarks, @Comments, @ProcesStat, @UpdateDate,              @OcrCode, @ACOMMENT, @VCOMMENT, @VerifiedStatus, @ApprovedStatus, @Flag;            WHILE @@FETCH_STATUS = 0          BEGIN              SET @DatabaseName = CASE                   WHEN @Branch = 'OIL' THEN @OilDatabase                   WHEN @Branch = 'BEVERAGE' THEN @BeverageDatabase                   ELSE NULL               END;                IF @DatabaseName IS NOT NULL              BEGIN                  -- Check if record exists                  SET @CheckQuery =                   'SELECT COUNT(*) FROM "' + @DatabaseName + '"."tbl_Draft_Approvals" ' +                  'WHERE "DocEntry" = ' + CAST(@DocEntry AS NVARCHAR) +                   ' AND "LineNum" = ' + CAST(@LineNum AS NVARCHAR) +                   ' AND "VisOrder" = ' + CAST(@VisOrder AS NVARCHAR) +                   ' AND "ObjType" = ' + CAST(@ObjType AS NVARCHAR);                    DECLARE @ResultTable TABLE (RecordExists INT);                  INSERT INTO @ResultTable EXEC (@CheckQuery) AT HANA112;                  SELECT @RecordExists = RecordExists FROM @ResultTable;                  DELETE FROM @ResultTable;                    IF @RecordExists = 0                  BEGIN                      -- Insert full row into HANA                      SET @SQLQuery =                       'INSERT INTO "' + @DatabaseName + '"."tbl_Draft_Approvals" ' +                      '("Branch", "DocEntry", "ObjectName", "ObjType", "LineNum", "VisOrder", ' +                      '"AcctCode", "AcctName", "CardCode", "CardName", "EFFECTMONTH", "BUDGET", "SUB_BUDGET", "STATE", ' +                      '"DocDate", "CreateDate", "AMOUNT", "CURRENTMONTH", "Current_month_Posted_Amount", ' +                      '"Budget_Owner", "OwnerCode", "ApproverName", "ApprovalCode", "Current_month_Budget", ' +                      '"Status", "U_NAME", "CreatedDate", "CreateTime", "LineRemarks", "Comments", "ProcesStat", ' +                      '"UpdateDate", "OcrCode", "ACOMMENT", "VCOMMENT", "VerifiedStatus", "ApprovedStatus") VALUES (' +                      '''' + ISNULL(@Branch, '') + ''', ' +                      CAST(@DocEntry AS NVARCHAR) + ', ' +                      '''' + ISNULL(@ObjectName, '') + ''', ' +                      CAST(@ObjType AS NVARCHAR) + ', ' +                      CAST(@LineNum AS NVARCHAR) + ', ' +                      CAST(@VisOrder AS NVARCHAR) + ', ' +                      '''' + ISNULL(@AcctCode, '') + ''', ' +                      '''' + ISNULL(@AcctName, '') + ''', ' +                      '''' + ISNULL(@CardCode, '') + ''', ' +                      '''' + ISNULL(@CardName, '') + ''', ' +                      '''' + ISNULL(@EFFECTMONTH, '') + ''', ' +                      '''' + ISNULL(@BUDGET, '') + ''', ' +                      '''' + ISNULL(@SUB_BUDGET, '') + ''', ' +                      '''' + ISNULL(@STATE, '') + ''', ' +                      '''' + CONVERT(NVARCHAR, @DocDate, 120) + ''', ' +                      '''' + CONVERT(NVARCHAR, @CreateDate, 120) + ''', ' +                      '''' + CAST(ISNULL(@AMOUNT, 0) AS NVARCHAR) + ''', ' +                      '''' + ISNULL(@CURRENTMONTH, '') + ''', ' +                      '''' + CAST(ISNULL(@Current_month_Posted_Amount, 0) AS NVARCHAR) + ''', ' +                      '''' + ISNULL(@Budget_Owner, '') + ''', ' +                      '''' + ISNULL(@OwnerCode, '') + ''', ' +                      '''' + ISNULL(@ApproverName, '') + ''', ' +                      '''' + ISNULL(@ApprovalCode, '') + ''', ' +                      '''' + CAST(ISNULL(@Current_month_Budget, 0) AS NVARCHAR) + ''', ' +                      '''' + ISNULL(@Status, '') + ''', ' +                      '''' + ISNULL(@U_NAME, '') + ''', ' +                      '''' + CONVERT(NVARCHAR, @CreatedDate, 120) + ''', ' +                      '''' + ISNULL(@CreateTime, '') + ''', ' +                      '''' + REPLACE(ISNULL(@LineRemarks, ''), '''', '''''') + ''', ' +                      '''' + REPLACE(ISNULL(@Comments, ''), '''', '''''') + ''', ' +                      '''' + ISNULL(@ProcesStat, '') + ''', ' +                      '''' + CONVERT(NVARCHAR, @UpdateDate, 120) + ''', ' +                      '''' + ISNULL(@OcrCode, '') + ''', ' +                      '''' + REPLACE(ISNULL(@ACOMMENT, ''), '''', '''''') + ''', ' +                      '''' + REPLACE(ISNULL(@VCOMMENT, ''), '''', '''''') + ''', ' +                      '''' + ISNULL(@VerifiedStatus, '') + ''', ' +                      '''' + ISNULL(@ApprovedStatus, '') + ''')';                        EXEC (@SQLQuery) AT HANA112;                  END                  ELSE                  BEGIN                      -- First, get the current UpdateDate from HANA                      DECLARE @CurrentUpdateDate DATETIME, @UpdateNeeded BIT = 0;                                            SET @CheckQuery =                       'SELECT "UpdateDate" FROM "' + @DatabaseName + '"."tbl_Draft_Approvals" ' +                      'WHERE "DocEntry" = ' + CAST(@DocEntry AS NVARCHAR) +                       ' AND "LineNum" = ' + CAST(@LineNum AS NVARCHAR) +                       ' AND "VisOrder" = ' + CAST(@VisOrder AS NVARCHAR) +                       ' AND "ObjType" = ' + CAST(@ObjType AS NVARCHAR);                        DECLARE @DateTable TABLE (UpdateDate DATETIME);                      INSERT INTO @DateTable EXEC (@CheckQuery) AT HANA112;                      SELECT @CurrentUpdateDate = UpdateDate FROM @DateTable;                      DELETE FROM @DateTable;                                            -- Check if UpdateDate has changed                      IF (@CurrentUpdateDate IS NULL AND @UpdateDate IS NOT NULL) OR                         (@CurrentUpdateDate IS NOT NULL AND @UpdateDate IS NULL) OR                         (@CurrentUpdateDate <> @UpdateDate)                      BEGIN                          SET @UpdateNeeded = 1;                      END                                            -- Only update if UpdateDate has changed                      IF @UpdateNeeded = 1                      BEGIN                          SET @SQLQuery =                           'UPDATE "' + @DatabaseName + '"."tbl_Draft_Approvals" SET ' +                          '"Branch" = ''' + ISNULL(@Branch, '') + ''', ' +                          '"ObjectName" = ''' + ISNULL(@ObjectName, '') + ''', ' +                          '"AcctCode" = ''' + ISNULL(@AcctCode, '') + ''', ' +                          '"AcctName" = ''' + ISNULL(@AcctName, '') + ''', ' +                          '"CardCode" = ''' + ISNULL(@CardCode, '') + ''', ' +                          '"CardName" = ''' + ISNULL(@CardName, '') + ''', ' +                          '"EFFECTMONTH" = ''' + ISNULL(@EFFECTMONTH, '') + ''', ' +                          '"BUDGET" = ''' + ISNULL(@BUDGET, '') + ''', ' +                          '"SUB_BUDGET" = ''' + ISNULL(@SUB_BUDGET, '') + ''', ' +                          '"STATE" = ''' + ISNULL(@STATE, '') + ''', ' +                          '"DocDate" = ''' + CONVERT(NVARCHAR, @DocDate, 120) + ''', ' +                          '"CreateDate" = ''' + CONVERT(NVARCHAR, @CreateDate, 120) + ''', ' +                          '"AMOUNT" = ''' + CAST(ISNULL(@AMOUNT, 0) AS NVARCHAR) + ''', ' +                          '"CURRENTMONTH" = ''' + ISNULL(@CURRENTMONTH, '') + ''', ' +                          '"Current_month_Posted_Amount" = ''' + CAST(ISNULL(@Current_month_Posted_Amount, 0) AS NVARCHAR) + ''', ' +                          '"Budget_Owner" = ''' + ISNULL(@Budget_Owner, '') + ''', ' +                          '"OwnerCode" = ''' + ISNULL(@OwnerCode, '') + ''', ' +                          '"ApproverName" = ''' + ISNULL(@ApproverName, '') + ''', ' +                          '"ApprovalCode" = ''' + ISNULL(@ApprovalCode, '') + ''', ' +                          '"Current_month_Budget" = ''' + CAST(ISNULL(@Current_month_Budget, 0) AS NVARCHAR) + ''', ' +                          '"Status" = ''' + ISNULL(@Status, '') + ''', ' +                          '"U_NAME" = ''' + ISNULL(@U_NAME, '') + ''', ' +                          '"CreatedDate" = ''' + CONVERT(NVARCHAR, @CreatedDate, 120) + ''', ' +                          '"CreateTime" = ''' + ISNULL(@CreateTime, '') + ''', ' +                          '"LineRemarks" = ''' + REPLACE(ISNULL(@LineRemarks, ''), '''', '''''') + ''', ' +                          '"Comments" = ''' + REPLACE(ISNULL(@Comments, ''), '''', '''''') + ''', ' +                          '"ProcesStat" = ''' + ISNULL(@ProcesStat, '') + ''', ' +                          '"UpdateDate" = ''' + CONVERT(NVARCHAR, @UpdateDate, 120) + ''', ' +                          '"OcrCode" = ''' + ISNULL(@OcrCode, '') + ''', ' +                          '"ACOMMENT" = ''' + REPLACE(ISNULL(@ACOMMENT, ''), '''', '''''') + ''', ' +                          '"VCOMMENT" = ''' + REPLACE(ISNULL(@VCOMMENT, ''), '''', '''''') + ''', ' +                          '"VerifiedStatus" = ''' + ISNULL(@VerifiedStatus, '') + ''', ' +                          '"ApprovedStatus" = ''' + ISNULL(@ApprovedStatus, '') + ''' ' +                          'WHERE "DocEntry" = ' + CAST(@DocEntry AS NVARCHAR) +                           ' AND "LineNum" = ' + CAST(@LineNum AS NVARCHAR) +                           ' AND "VisOrder" = ' + CAST(@VisOrder AS NVARCHAR) +                           ' AND "ObjType" = ' + CAST(@ObjType AS NVARCHAR);                                                    EXEC (@SQLQuery) AT HANA112;                      END                  END              END                FETCH NEXT FROM record_cursor INTO                   @Branch, @DocEntry, @ObjectName, @ObjType, @LineNum, @VisOrder,                  @AcctCode, @AcctName, @CardCode, @CardName, @EFFECTMONTH, @BUDGET,                  @SUB_BUDGET, @STATE, @DocDate, @CreateDate, @AMOUNT, @CURRENTMONTH,                  @Current_month_Posted_Amount, @Budget_Owner, @OwnerCode, @ApproverName,                  @ApprovalCode, @Current_month_Budget, @Status, @U_NAME, @CreatedDate,                  @CreateTime, @LineRemarks, @Comments, @ProcesStat, @UpdateDate,                  @OcrCode, @ACOMMENT, @VCOMMENT, @VerifiedStatus, @ApprovedStatus, @Flag;          END            CLOSE record_cursor;          DEALLOCATE record_cursor;            DROP TABLE #TempWithoutFlag;          DROP TABLE #TempTable;        END TRY      BEGIN CATCH          IF CURSOR_STATUS('global', 'record_cursor') >= 0          BEGIN              CLOSE record_cursor;              DEALLOCATE record_cursor;          END            IF OBJECT_ID('tempdb..#TempWithoutFlag') IS NOT NULL DROP TABLE #TempWithoutFlag;          IF OBJECT_ID('tempdb..#TempTable') IS NOT NULL DROP TABLE #TempTable;            THROW;      END CATCH  END
